"""Solvers written directly from the problem definitions.

solve_hamiltonian_path: brute force over permutations.
solve_sat: DPLL with unit propagation (exact, handles empty clauses,
repeated literals and tautologies).
"""

from __future__ import annotations

from itertools import permutations
from typing import Any


def solve_hamiltonian_path(instance: dict[str, Any]) -> bool:
    n = instance["n"]
    edges = {frozenset((u, v)) for u, v in instance["edges"]}
    if n == 0:
        return False
    if n == 1:
        return True
    for perm in permutations(range(n)):
        if all(frozenset((perm[i], perm[i + 1])) in edges for i in range(n - 1)):
            return True
    return False


def _simplify(clauses, assignment):
    """Apply assignment; return simplified clauses or None if unsatisfiable."""
    result = []
    for clause in clauses:
        new_clause = []
        satisfied = False
        for lit in clause:
            var = abs(lit)
            if var in assignment:
                val = assignment[var]
                if (lit > 0) == val:
                    satisfied = True
                    break
            else:
                new_clause.append(lit)
        if satisfied:
            continue
        if not new_clause:
            return None
        result.append(new_clause)
    return result


def _dpll(clauses, assignment):
    clauses = _simplify(clauses, assignment)
    if clauses is None:
        return False
    if not clauses:
        return True

    # Unit propagation.
    while True:
        unit = None
        for clause in clauses:
            if len(clause) == 1:
                unit = clause[0]
                break
        if unit is None:
            break
        assignment[unit if unit > 0 else -unit] = unit > 0
        clauses = _simplify(clauses, assignment)
        if clauses is None:
            return False
        if not clauses:
            return True

    # Pure literal elimination (optional, helps a lot).
    while True:
        pos = set()
        neg = set()
        for clause in clauses:
            for lit in clause:
                (pos if lit > 0 else neg).add(abs(lit))
        pure = None
        for var in pos:
            if var not in neg:
                pure = var
                break
        if pure is None:
            for var in neg:
                if var not in pos:
                    pure = -var
                    break
        if pure is None:
            break
        assignment[abs(pure)] = pure > 0
        clauses = _simplify(clauses, assignment)
        if clauses is None:
            return False
        if not clauses:
            return True

    # Branch on the variable with most occurrences.
    counts: dict[int, int] = {}
    for clause in clauses:
        for lit in clause:
            counts[abs(lit)] = counts.get(abs(lit), 0) + 1
    var = max(counts, key=counts.get)

    for value in (True, False):
        new_assignment = dict(assignment)
        new_assignment[var] = value
        if _dpll(clauses, new_assignment):
            return True
    return False


def solve_sat(instance: dict[str, Any]) -> bool:
    clauses = [list(clause) for clause in instance["clauses"]]
    return _dpll(clauses, {})
EOF
